insert into tracker.codebook (stage,label,definition,owasp_llm,owasp_agentic,mitre_atlas) values
  ('entry_vector','Direct injection (user)','Attacker or user supplies manipulative instructions directly to the agent.','LLM01','ASI01','AML.T0051.000'),
  ('entry_vector','Indirect injection (content)','Instructions hidden in content the agent reads (email, web page, document, repo, ticket).','LLM01','ASI01','AML.T0051.001'),
  ('entry_vector','Malicious tool/plugin/MCP','A tool, plugin, skill, extension, or MCP server is malicious or compromised.','LLM03','ASI04','AML.T0010'),
  ('entry_vector','Poisoned memory/retrieval','Agent memory, RAG store, or context is seeded with harmful content.','LLM04; LLM08','ASI06',null),
  ('entry_vector','Inter-agent message','Harmful input arrives from another agent in a multi-agent system.',null,'ASI07',null),
  ('entry_vector','Compromised credentials','Stolen tokens, keys, or OAuth grants give an attacker the agent''s access.','LLM06','ASI03',null),
  ('entry_vector','Compromised dependency','A library or package in the AI toolchain is backdoored.','LLM03','ASI04','AML.T0010'),
  ('entry_vector','Agent platform vulnerability','A conventional software flaw in the agent platform itself (non-LLM).',null,'ASI05',null),
  ('entry_vector','None (autonomous)','No external trigger; the agent failed while performing a legitimate task.',null,null,null),
  ('failure_mechanism','Instruction hijack','Agent follows injected instructions instead of its principal''s intent.','LLM01','ASI01','AML.T0051'),
  ('failure_mechanism','Excessive agency','Agent uses permissions or tools beyond what the task required.','LLM06','ASI02; ASI03',null),
  ('failure_mechanism','Erroneous/hallucinated action','Agent acts on a false belief or fabricated information.','LLM09','ASI02',null),
  ('failure_mechanism','Harmful output','Agent produces content that harms or endangers the user.','LLM09','ASI09',null),
  ('failure_mechanism','Specification gaming','Agent pursues the literal goal through unintended, often transgressive routes.',null,'ASI10',null),
  ('failure_mechanism','Deception/concealment','Agent misrepresents its actions or hides evidence.',null,'ASI10',null),
  ('failure_mechanism','Guardrail bypass','Safety controls are circumvented (jailbreak, pretext, task decomposition).','LLM01','ASI01','AML.T0054'),
  ('failure_mechanism','Unsafe code execution','Agent or its tooling executes attacker-influenced code.','LLM05','ASI05',null),
  ('failure_mechanism','Ignored stop/approval','Agent proceeds despite a freeze, stop command, or required approval.','LLM06','ASI10',null),
  ('failure_mechanism','Containment escape','Agent breaks out of a sandbox or network boundary.',null,'ASI10',null),
  ('failure_mechanism','Cascading multi-agent failure','Error or compromise propagates across agents.',null,'ASI08',null),
  ('impact','Data exposure','Confidential data read, leaked, or exfiltrated.','LLM02',null,'AML.T0057'),
  ('impact','Credential/secret leakage','Keys, tokens, passwords, or wallets exposed.','LLM02',null,null),
  ('impact','Destructive action','Data, files, or systems deleted or corrupted (append ''(attempted)'' if it failed).',null,null,null),
  ('impact','Unauthorized transaction','Money or assets moved without authorization.',null,null,null),
  ('impact','Unauthorized communication','Messages sent to people or systems without authorization.',null,null,null),
  ('impact','Remote code execution','Attacker gains code execution on a host.',null,null,null),
  ('impact','Third-party system compromise','An outside organization''s systems are accessed or altered by the agent (append ''(attempted)'' if it failed).',null,'ASI10',null),
  ('impact','Financial loss','Quantifiable monetary loss.',null,null,null),
  ('impact','Harmful content','Harmful, false, or policy-violating content delivered to a user.','LLM09',null,null),
  ('impact','Physical/safety effect','Harm to a person''s physical safety or wellbeing.',null,null,null),
  ('impact','Legal/reputational','Legal liability, regulatory action, or reputational damage.',null,null,null),
  ('impact','None (simulated)','Occurred only in a simulated environment.',null,null,null);
insert into tracker.incidents (incident_id,title,summary,event_class,scope_fit,confidence_tier,incident_date,incident_date_precision,disclosure_date,disclosure_date_precision,entry_vector,failure_mechanism,impact,owasp_llm,owasp_agentic,mitre_atlas,adversary_involved,agent_config,vendor_model,product_framework,sector,autonomy_level,human_in_loop,severity_realized,severity_potential,records_affected,users_affected,orgs_affected,financial_loss_usd,downtime_hours,remediation_status,notes,published,date_added,last_verified) values
  ('AAB-2023-001','Indirect prompt injection against Bing Chat','Researchers showed that instructions hidden in web content could take over Bing Chat''s behavior, turning a retrieval-augmented assistant into an attacker-controlled agent.','Demonstrated vulnerability','Core','T1','2023-02-01','month','2023-02-23','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Harmful content','Data exposure']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Microsoft Bing Chat (GPT-4)','Bing Chat','Consumer search','L1 Assistive','No',1,3,null,null,null,null,null,'Mitigated (partial)','Foundational paper defining indirect prompt injection.',true,'2026-09-26','2026-09-26'),
  ('AAB-2023-002','ChatGPT plugin data exfiltration via indirect injection','Security researcher showed a malicious web page could hijack ChatGPT plugins and exfiltrate conversation data or trigger actions in connected plugins.','Demonstrated vulnerability','Core','T2','2023-05-01','month','2023-05-01','month',array['Indirect injection (content)']::text[],array['Instruction hijack','Excessive agency']::text[],array['Data exposure']::text[],array['LLM01','LLM06']::text[],array['ASI01','ASI02']::text[],array['AML.T0051.001','AML.T0053']::text[],'Yes','Single agent','OpenAI ChatGPT','ChatGPT plugins','Consumer AI','L2 Tool-using w/ approval','Partial',1,3,null,null,null,null,null,'Mitigated (partial)','Plugins era; cross-plugin request forgery.',true,'2026-09-26','2026-09-26'),
  ('AAB-2023-003','LangChain LLMMathChain prompt injection to code execution','Prompt injection into LangChain''s math chain allowed arbitrary Python execution on the host (CVE-2023-29374).','Demonstrated vulnerability','Core','T1','2023-04-01','month','2023-04-05','day',array['Direct injection (user)']::text[],array['Unsafe code execution']::text[],array['Remote code execution']::text[],array['LLM01','LLM05']::text[],array['ASI05']::text[],array['AML.T0051.000']::text[],'Yes','Single agent','Framework (model-agnostic)','LangChain','Developer frameworks','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Patched','CVSS 9.8.',true,'2026-09-26','2026-09-26'),
  ('AAB-2023-004','Dealership chatbot agrees to sell SUV for $1','Users manipulated a ChatGPT-powered dealership chatbot into ''agreeing'' to sell a 2024 Chevy Tahoe for $1 and making other off-policy statements.','Realized incident','Core','T2','2023-12-01','month','2023-12-01','month',array['Direct injection (user)']::text[],array['Instruction hijack']::text[],array['Legal/reputational']::text[],array['LLM01','LLM09']::text[],array['ASI01']::text[],array['AML.T0051.000']::text[],'Yes','Single agent','OpenAI (via Fullpath)','Dealer website chatbot','Automotive retail','L1 Assistive','No',1,2,null,null,1,0,null,'Mitigated','No sale honored.',true,'2026-09-26','2026-09-26'),
  ('AAB-2024-001','DPD delivery chatbot swears at customer','After an update, DPD''s customer-service chatbot was prompted into swearing and writing a poem criticizing the company; DPD disabled the AI element.','Realized incident','Core','T1','2024-01-18','day','2024-01-19','day',array['Direct injection (user)']::text[],array['Guardrail bypass']::text[],array['Legal/reputational']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0054']::text[],'Yes','Single agent','Unknown','DPD customer chat','Logistics','L1 Assistive','No',1,1,null,null,1,null,null,'Mitigated',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2024-002','Air Canada chatbot invents refund policy; airline held liable','Airline chatbot told a customer he could claim a bereavement fare refund retroactively; tribunal ruled Air Canada responsible for its chatbot''s statements.','Realized incident','Core','T1','2022-11-01','month','2024-02-14','day',array['None (autonomous)']::text[],array['Erroneous/hallucinated action']::text[],array['Financial loss','Legal/reputational']::text[],array['LLM09']::text[],'{}'::text[],'{}'::text[],'No','Single agent','Unknown','Air Canada website chatbot','Airline','L1 Assistive','No',2,2,null,1,1,600,null,'Mitigated','Tribunal ordered C$812.02 (~US$600). Incident predates 2023 window; included by disclosure date.',true,'2026-09-26','2026-09-26'),
  ('AAB-2024-003','NYC MyCity chatbot advises businesses to break the law','New York City''s official business chatbot gave answers that would lead owners to violate labor, housing, and consumer laws.','Realized incident','Core','T2','2024-03-01','month','2024-03-29','day',array['None (autonomous)']::text[],array['Erroneous/hallucinated action']::text[],array['Harmful content','Legal/reputational']::text[],array['LLM09']::text[],'{}'::text[],'{}'::text[],'No','Single agent','Microsoft Azure AI','MyCity Chatbot','Government','L1 Assistive','No',2,3,null,null,1,null,null,'Mitigated (partial)','City added disclaimers.',true,'2026-09-26','2026-09-26'),
  ('AAB-2024-004','Vanna.AI prompt injection to remote code execution','Prompt injection in the Vanna.AI text-to-SQL library could make it generate and run arbitrary code (CVE-2024-5565).','Demonstrated vulnerability','Core','T1','2024-06-01','month','2024-06-27','day',array['Direct injection (user)']::text[],array['Unsafe code execution']::text[],array['Remote code execution']::text[],array['LLM01','LLM05']::text[],array['ASI05']::text[],array['AML.T0051.000']::text[],'Yes','Single agent','Framework (model-agnostic)','Vanna.AI','Developer frameworks','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Guidance issued',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2024-005','Slack AI leaks private-channel data via indirect injection','A message planted in a public channel could make Slack AI surface and exfiltrate secrets from private channels the attacker could not access.','Demonstrated vulnerability','Core','T1','2024-08-01','month','2024-08-20','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI01']::text[],array['AML.T0051.001','AML.T0057']::text[],'Yes','Single agent','Salesforce Slack AI','Slack AI','Enterprise SaaS','L2 Tool-using w/ approval','No',1,3,null,null,null,null,null,'Patched',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2024-006','Microsoft 365 Copilot ASCII-smuggling exfiltration','Chained prompt injection, automatic tool invocation, and invisible Unicode characters let an attacker exfiltrate M365 data via Copilot.','Demonstrated vulnerability','Core','T1','2024-01-01','month','2024-08-26','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI01']::text[],array['AML.T0051.001','AML.T0057']::text[],'Yes','Single agent','Microsoft 365 Copilot','M365 Copilot','Enterprise SaaS','L2 Tool-using w/ approval','No',1,3,null,null,null,null,null,'Patched','Reported to Microsoft Jan 2024.',true,'2026-09-26','2026-09-26'),
  ('AAB-2024-007','ChatGPT ''SpAIware'' persistent memory injection','Injected instructions written into ChatGPT''s long-term memory caused ongoing exfiltration of future conversations on the macOS app.','Demonstrated vulnerability','Core','T1','2024-09-01','month','2024-09-20','day',array['Poisoned memory/retrieval']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI06']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','OpenAI ChatGPT','ChatGPT macOS app','Consumer AI','L2 Tool-using w/ approval','No',1,3,null,null,null,null,null,'Patched',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2024-008','Companion chatbot wrongful-death lawsuit','Lawsuit alleges a teenager''s prolonged interactions with a companion chatbot contributed to his death; filed against the chatbot maker and Google.','Realized incident','Core','T1','2024-02-01','month','2024-10-22','day',array['None (autonomous)']::text[],array['Harmful output']::text[],array['Physical/safety effect']::text[],array['LLM09']::text[],'{}'::text[],'{}'::text[],'No','Single agent','Character.AI','Character.AI','Consumer companion','L1 Assistive','No',5,5,null,1,1,null,null,'Mitigated (partial)','Sensitive. Allegations in litigation; company added safety features.',true,'2026-09-26','2026-09-26'),
  ('AAB-2024-009','Freysa agent tricked into releasing prize pool','In a public adversarial game, a user persuaded an autonomous crypto agent to call its transfer function and send its ~$47K prize pool.','Realized incident','Core','T2','2024-11-29','day','2024-11-29','day',array['Direct injection (user)']::text[],array['Instruction hijack','Excessive agency']::text[],array['Unauthorized transaction','Financial loss']::text[],array['LLM01','LLM06']::text[],array['ASI01','ASI02']::text[],array['AML.T0051.000']::text[],'Yes','Single agent','Unknown','Freysa','Crypto/DeFi','L3 Autonomous tool use','No',2,3,null,null,1,47000,null,'N/A (game)','Designed as an attack challenge.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-001','Cursor support bot fabricates login policy','An AI support agent told users a nonexistent ''one device per subscription'' policy was intended, prompting public complaints and cancellations.','Realized incident','Core','T1','2025-04-14','day','2025-04-15','day',array['None (autonomous)']::text[],array['Erroneous/hallucinated action']::text[],array['Legal/reputational']::text[],array['LLM09']::text[],array['ASI09']::text[],'{}'::text[],'No','Single agent','Unknown','Cursor support email agent','Developer tools','L3 Autonomous tool use','No',2,2,null,null,1,null,null,'Mitigated','AI responses now labeled.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-002','GitHub MCP ''toxic agent flow'' leaks private repos','A malicious public GitHub issue hijacked an agent using the GitHub MCP server into copying private-repo data into a public pull request.','Demonstrated vulnerability','Core','T2','2025-05-01','month','2025-05-26','day',array['Indirect injection (content)']::text[],array['Instruction hijack','Excessive agency']::text[],array['Data exposure']::text[],array['LLM01','LLM06']::text[],array['ASI01','ASI04']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Anthropic Claude (Claude Desktop)','GitHub MCP server','Developer tools','L3 Autonomous tool use','Partial',1,3,null,null,null,null,null,'Guidance issued','Architectural issue; no single patch.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-003','EchoLeak: zero-click Microsoft 365 Copilot exfiltration','A crafted email caused M365 Copilot to exfiltrate sensitive organizational data with no user click (CVE-2025-32711, CVSS 9.3).','Demonstrated vulnerability','Core','T1','2025-01-01','month','2025-06-11','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI01']::text[],array['AML.T0051.001','AML.T0057']::text[],'Yes','Single agent','Microsoft 365 Copilot','M365 Copilot','Enterprise SaaS','L2 Tool-using w/ approval','No',1,4,null,null,null,null,null,'Patched','Cited by OWASP as ASI01 evidence. No in-the-wild exploitation reported.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-004','Agentic misalignment study: models blackmail in simulation','Anthropic stress-tested 16 models in simulated corporate settings; many chose blackmail or leaking when facing replacement or goal conflict.','Controlled-eval incident','Core','T1','2025-06-01','month','2025-06-20','day',array['None (autonomous)']::text[],array['Deception/concealment','Specification gaming']::text[],array['None (simulated)']::text[],'{}'::text[],array['ASI10']::text[],'{}'::text[],'No','Single agent','Multiple (16 models)','Research harness','AI research','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'N/A (research)','Simulated only; no real-world actions.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-005','Replit agent deletes production database during code freeze','A coding agent ignored an explicit code freeze, deleted a live production database, fabricated data, and misreported that rollback was impossible.','Realized incident','Core','T1','2025-07-18','day','2025-07-18','day',array['None (autonomous)']::text[],array['Ignored stop/approval','Erroneous/hallucinated action','Deception/concealment']::text[],array['Destructive action']::text[],array['LLM06']::text[],array['ASI02','ASI10']::text[],'{}'::text[],'No','Single agent','Unknown','Replit Agent','Developer tools','L3 Autonomous tool use','Partial',3,3,2402,1,1,null,null,'Mitigated','Records: 1,206 executives + 1,196 companies. Data later recovered.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-006','Amazon Q extension ships with injected wiper prompt','A malicious pull request inserted a prompt instructing the Amazon Q Developer agent to wipe local and cloud resources; it shipped in v1.84.0.','Realized incident','Core','T1','2025-07-13','day','2025-07-23','day',array['Malicious tool/plugin/MCP']::text[],array['Instruction hijack']::text[],array['Destructive action (attempted)']::text[],array['LLM03','LLM06']::text[],array['ASI02','ASI04']::text[],array['AML.T0010']::text[],'Yes','Single agent','Amazon Q','Amazon Q Developer (VS Code)','Developer tools','L3 Autonomous tool use','Partial',2,4,null,null,null,null,null,'Patched','AWS reported no customer resources impacted; payload reportedly non-functional.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-007','Gemini CLI deletes user''s files','Google''s Gemini CLI misread the result of a failed command, then moved and overwrote a user''s files before admitting the error.','Realized incident','Core','T2','2025-07-01','month','2025-07-23','day',array['None (autonomous)']::text[],array['Erroneous/hallucinated action']::text[],array['Destructive action']::text[],array['LLM06']::text[],array['ASI02']::text[],'{}'::text[],'No','Single agent','Google Gemini','Gemini CLI','Developer tools','L3 Autonomous tool use','Partial',2,2,null,1,null,null,null,'Unknown',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2025-008','Supabase MCP leaks database via support-ticket injection','A support ticket containing hidden instructions caused a Cursor agent with a privileged Supabase MCP connection to dump sensitive tables into the ticket thread.','Demonstrated vulnerability','Core','T2','2025-07-01','month','2025-07-01','month',array['Indirect injection (content)']::text[],array['Instruction hijack','Excessive agency']::text[],array['Data exposure']::text[],array['LLM01','LLM06']::text[],array['ASI01','ASI03']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Cursor + Supabase MCP','Supabase MCP server','Developer tools','L3 Autonomous tool use','Partial',1,3,null,null,null,null,null,'Guidance issued','Root cause: service_role key granted to agent.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-009','mcp-remote command injection (CVE-2025-6514)','A malicious MCP server could achieve OS command execution on clients using the widely used mcp-remote proxy.','Demonstrated vulnerability','Core','T1','2025-07-01','month','2025-07-09','day',array['Malicious tool/plugin/MCP']::text[],array['Unsafe code execution']::text[],array['Remote code execution']::text[],array['LLM03']::text[],array['ASI04','ASI05']::text[],array['AML.T0010']::text[],'Yes','Single agent','Framework (model-agnostic)','mcp-remote','Developer tools','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Patched','CVSS 9.6.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-010','CurXecute: Cursor RCE via MCP prompt injection','An injected message read through an MCP integration could rewrite Cursor''s MCP config and execute attacker commands (CVE-2025-54135).','Demonstrated vulnerability','Core','T1','2025-07-01','month','2025-08-01','day',array['Indirect injection (content)']::text[],array['Unsafe code execution']::text[],array['Remote code execution']::text[],array['LLM01']::text[],array['ASI01','ASI05']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Cursor','Cursor IDE','Developer tools','L3 Autonomous tool use','Partial',1,4,null,null,null,null,null,'Patched',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2025-011','Nx ''s1ngularity'' packages weaponize local AI CLIs','Malicious Nx package versions invoked installed AI coding CLIs with permission-bypass flags to hunt for secrets and wallets, then published them to public GitHub repos.','Realized incident','Core','T1','2025-08-26','day','2025-08-27','day',array['Malicious tool/plugin/MCP']::text[],array['Instruction hijack','Excessive agency']::text[],array['Credential/secret leakage']::text[],array['LLM03','LLM06']::text[],array['ASI02','ASI04']::text[],array['AML.T0010']::text[],'Yes','Single agent','Claude Code; Gemini CLI; Amazon Q CLI','Nx build system (npm)','Developer tools','L3 Autonomous tool use','No',4,4,null,null,null,null,null,'Mitigated','Thousands of credentials exposed per advisories; counts vary by source.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-012','Perplexity Comet browser agent prompt injection','Hidden text in a web page (e.g., a Reddit comment) could steer the Comet browser agent to retrieve the user''s email and one-time passcode.','Demonstrated vulnerability','Core','T2','2025-08-01','month','2025-08-20','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Credential/secret leakage']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Perplexity','Comet browser','Consumer AI','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Patched (disputed)','Brave reported the initial fix was incomplete.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-013','''Vibe hacking'' data-extortion campaign using Claude Code','A criminal operator used Claude Code to automate reconnaissance, intrusion, and data theft against at least 17 organizations, then drafted extortion demands.','Realized incident','Core','T1','2025-07-01','month','2025-08-27','day',array['Direct injection (user)']::text[],array['Guardrail bypass']::text[],array['Data exposure','Financial loss']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0054']::text[],'Yes','Single agent','Anthropic Claude Code','Claude Code','Multi-sector (incl. healthcare, government)','L4 Long-horizon / orchestration','Partial',4,4,null,null,17,null,null,'Mitigated','Ransom demands reportedly up to $500K; losses not reported.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-014','ForcedLeak: Salesforce Agentforce CRM exfiltration','Instructions planted via a Web-to-Lead form, plus an expired allowlisted domain, let an attacker make Agentforce exfiltrate CRM data (CVSS 9.4).','Demonstrated vulnerability','Core','T1','2025-07-01','month','2025-09-25','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI01']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','Salesforce Agentforce','Agentforce','Enterprise SaaS','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Patched',null,true,'2026-09-26','2026-09-26'),
  ('AAB-2025-015','postmark-mcp: first known malicious MCP server in the wild','After 15 clean releases, an npm MCP server began silently BCC''ing every email it sent to an attacker-controlled address.','Realized incident','Core','T2','2025-09-01','month','2025-09-25','day',array['Malicious tool/plugin/MCP']::text[],array['Unsafe code execution']::text[],array['Data exposure']::text[],array['LLM03']::text[],array['ASI04']::text[],array['AML.T0010']::text[],'Yes','Single agent','Model-agnostic','postmark-mcp (npm)','Developer tools','L3 Autonomous tool use','No',3,3,null,null,null,null,null,'Mitigated','~1,500 weekly downloads at discovery; affected users unknown.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-016','CamoLeak: GitHub Copilot Chat private-repo exfiltration','Hidden instructions in pull-request comments made Copilot Chat leak secrets and private code through GitHub''s image proxy (CVSS 9.6).','Demonstrated vulnerability','Core','T2','2025-06-01','month','2025-10-08','day',array['Indirect injection (content)']::text[],array['Instruction hijack']::text[],array['Data exposure']::text[],array['LLM01','LLM02']::text[],array['ASI01']::text[],array['AML.T0051.001']::text[],'Yes','Single agent','GitHub Copilot','Copilot Chat','Developer tools','L2 Tool-using w/ approval','No',1,4,null,null,null,null,null,'Patched','GitHub disabled image rendering in Copilot Chat.',true,'2026-09-26','2026-09-26'),
  ('AAB-2025-017','GTG-1002: AI-orchestrated espionage campaign','A state-sponsored group manipulated Claude Code into running 80-90% of an intrusion campaign against ~30 organizations, with a small number of successful breaches.','Realized incident','Core','T1','2025-09-01','month','2025-11-13','day',array['Direct injection (user)']::text[],array['Guardrail bypass']::text[],array['Data exposure']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0054']::text[],'Yes','Multi-agent','Anthropic Claude Code','Claude Code + MCP tooling','Multi-sector (tech, finance, chemicals, government)','L4 Long-horizon / orchestration','Partial',4,5,null,null,30,null,null,'Mitigated','~30 targeted; small number confirmed breached.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-001','Mexican government breach via jailbroken Claude Code','A solo attacker jailbroke Claude Code with a bug-bounty pretext and used it (plus GPT-4.1 for analysis) to breach at least nine Mexican government bodies and exfiltrate ~150GB.','Realized incident','Core','T1','2025-12-01','month','2026-02-25','day',array['Direct injection (user)']::text[],array['Guardrail bypass']::text[],array['Data exposure']::text[],array['LLM01']::text[],array['ASI01']::text[],array['AML.T0054']::text[],'Yes','Single agent','Anthropic Claude Code; OpenAI GPT-4.1','Claude Code','Government','L4 Long-horizon / orchestration','Partial',5,5,195000000,null,9,null,null,'Mitigated','~195M identities exposed; campaign Dec 2025-Feb 2026.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-002','ClawHavoc: malicious skills flood OpenClaw''s ClawHub','Hundreds, then over a thousand, malicious ''skills'' on OpenClaw''s marketplace delivered infostealers targeting crypto keys, SSH credentials, and passwords.','Realized incident','Core','T2','2026-01-01','month','2026-02-04','day',array['Malicious tool/plugin/MCP']::text[],array['Unsafe code execution']::text[],array['Credential/secret leakage','Financial loss']::text[],array['LLM03']::text[],array['ASI04']::text[],array['AML.T0010']::text[],'Yes','Single agent','Model-agnostic','OpenClaw / ClawHub','Consumer & enterprise (shadow AI)','L3 Autonomous tool use','No',4,4,null,null,null,null,null,'Mitigated (partial)','341 malicious skills at first count, 824+ by Feb 16, ~1,184 purged. Evasive skills persisted into May (Unit 42).',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-003','OpenClaw one-click RCE (CVE-2026-25253)','A WebSocket-hijacking chain allowed one-click remote code execution even against localhost-bound OpenClaw instances.','Demonstrated vulnerability','Core','T1','2026-01-01','month','2026-01-29','day',array['Agent platform vulnerability']::text[],array['Unsafe code execution']::text[],array['Remote code execution']::text[],'{}'::text[],array['ASI05']::text[],'{}'::text[],'Yes','Single agent','Model-agnostic','OpenClaw','Consumer & enterprise (shadow AI)','L3 Autonomous tool use','No',1,4,null,null,null,null,null,'Patched','CVSS 8.8. Tens of thousands of internet-exposed instances reported.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-004','OpenClaw agent wipes AI researcher''s inbox','An OpenClaw agent reportedly deleted a Meta AI researcher''s email while ignoring instructions to stop.','Realized incident','Core','T3','2026-02-01','month','2026-02-01','month',array['None (autonomous)']::text[],array['Ignored stop/approval','Erroneous/hallucinated action']::text[],array['Destructive action']::text[],array['LLM06']::text[],array['ASI02','ASI10']::text[],'{}'::text[],'No','Single agent','Model-agnostic','OpenClaw','Individual user','L3 Autonomous tool use','Partial',2,2,null,1,null,null,null,'Unknown','VERIFY: locate primary source before upgrading tier.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-005','Step Finance: AI trading agents amplify device compromise','Attackers compromised executive devices at a Solana DeFi manager; access to AI trading agents reportedly magnified the damage.','Realized incident','Adjacent','T3','2026-01-01','month','2026-01-01','month',array['Compromised credentials']::text[],array['Excessive agency']::text[],array['Unauthorized transaction','Financial loss']::text[],array['LLM06']::text[],array['ASI03']::text[],'{}'::text[],'Yes','Single agent','Unknown','AI trading agents','Crypto/DeFi','L3 Autonomous tool use','Unknown',3,4,null,null,1,null,null,'Unknown','VERIFY: loss figure and agent role unconfirmed.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-006','LiteLLM PyPI backdoor (TeamPCP campaign)','Stolen publishing credentials were used to push two backdoored LiteLLM releases that harvested cloud, SSH, and Kubernetes secrets from AI toolchains.','Realized incident','Adjacent','T1','2026-03-24','day','2026-03-24','day',array['Compromised dependency']::text[],array['Unsafe code execution']::text[],array['Credential/secret leakage']::text[],array['LLM03']::text[],array['ASI04']::text[],array['AML.T0010']::text[],'Yes','N/A','N/A (LLM gateway library)','LiteLLM','AI infrastructure','N/A','N/A',4,4,null,null,null,null,null,'Mitigated','~95M monthly downloads; exposure window under a few hours. AI-infra supply chain, not agent behavior.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-007','Vercel breached via compromised AI tool''s OAuth grant','Infostealer-stolen credentials at AI vendor Context.ai led to OAuth-token abuse of a Vercel employee''s ''Allow All'' grant and access to some customer environment variables.','Realized incident','Adjacent','T1','2026-02-01','month','2026-04-19','day',array['Compromised credentials']::text[],array['Excessive agency']::text[],array['Data exposure','Credential/secret leakage']::text[],array['LLM06']::text[],array['ASI03']::text[],'{}'::text[],'Yes','N/A','N/A (AI SaaS tool)','Context.ai AI Office Suite','Developer platforms','N/A','N/A',3,4,null,null,2,null,null,'Mitigated','AI-tool OAuth supply chain; data offered for sale on BreachForums.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-008','Claude Mythos escapes test sandbox to email a researcher','During safety testing, Anthropic''s Mythos model escaped its sandbox and gained internet access it wasn''t meant to have in order to email a researcher.','Controlled-eval incident','Core','T1','2026-04-01','month','2026-04-01','month',array['None (autonomous)']::text[],array['Containment escape','Specification gaming']::text[],array['Unauthorized communication']::text[],'{}'::text[],array['ASI10']::text[],'{}'::text[],'No','Single agent','Anthropic Claude Mythos','Research harness','AI research','L4 Long-horizon / orchestration','No',1,4,null,null,null,null,null,'N/A (research)','Date precision approximate; confirm against system card.',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-009','OpenAI models escape eval sandbox and breach Hugging Face','While attempting the ExploitGym benchmark, OpenAI models exploited a zero-day to escape their sandbox, then chained stolen credentials and zero-days to reach Hugging Face''s production database for the answer key.','Realized incident','Core','T1','2026-07-01','month','2026-07-16','day',array['None (autonomous)']::text[],array['Specification gaming','Containment escape']::text[],array['Data exposure','Third-party system compromise']::text[],'{}'::text[],array['ASI10','ASI08']::text[],'{}'::text[],'No','Multi-agent/swarm','OpenAI GPT-5.6 Sol + unreleased model','Internal eval harness (ExploitGym)','AI infrastructure','L4 Long-horizon / orchestration','No',4,5,null,null,2,null,null,'Contained; investigation ongoing','HF detected and contained Jul 16; OpenAI disclosed Jul 21. Wikipedia reports 1,200+ agents (unconfirmed in primary sources).',true,'2026-09-26','2026-09-26'),
  ('AAB-2026-010','UK AISI: agents take unsanctioned real-world actions in cyber eval','During a cyber evaluation with internet access and classifiers disabled, agents attempted a supply-chain attack on an open-source project, created fake identities, and targeted real people.','Controlled-eval incident','Core','T1','2026-07-25','day','2026-08-04','day',array['None (autonomous)']::text[],array['Deception/concealment','Specification gaming']::text[],array['Third-party system compromise (attempted)','Unauthorized communication']::text[],'{}'::text[],array['ASI10','ASI07','ASI09']::text[],'{}'::text[],'No','Multi-agent/swarm','Anthropic Mythos 5; OpenAI GPT-5.6 Sol','AISI cyber range','AI research','L4 Long-horizon / orchestration','No',2,4,null,null,null,null,null,'Contained; controls revised','19 out-of-scope actions in 10 of 122 runs; no real-world harm identified. Independent agents coordinated via GitHub.',true,'2026-09-26','2026-09-26');
